    if len(grid) != 12 or any(len(row) != 6 for row in grid):
        raise ValueError("expected a 12x6 grid")
    out = [row[:] for row in grid[:3]]
    # Apply low-to-high priority so the highest-priority nonzero lower color wins.
    for start in (6, 9, 3):  # color panels 2, 8, 4
        for r in range(3):
            for c in range(6):
                value = grid[start + r][c]
                if value != 0 and out[r][c] != 5:
                    out[r][c] = value
    return out
